import { businessDate } from '@/app/admin/_lib/business-date'
import { createClient } from '@/lib/supabase/server'
import { openRegistrationStatuses, shownCount, tabMode, tabStatuses } from './model'

export const pageSize = 25

export type LeadFilters = {
  tab?: string
  queue?: string
  status?: string
  branch?: string
  owner?: string
  source?: string
  interest_level?: string
  interest?: string
  follow?: string
  q?: string
  page?: string
}

export type LeadRow = {
  id: string
  full_name: string | null
  phone: string | null
  email: string | null
  parent_name: string | null
  student_name: string | null
  source_type: string
  interest_level: string
  program_interest: string | null
  instrument_interest: string | null
  branch_id: string
  owner_user_id: string | null
  status: string
  last_contact_at: string | null
  next_follow_up_on: string | null
  converted_student_id: string | null
  version: number
  created_at: string
}

export type RegistrationSummary = {
  id: string
  crm_lead_id: string | null
  status: string
  application_code: string
  linked_student_id: string | null
  invoice_id: string | null
  payment_confirmed_at: string | null
}

const leadColumns = 'id, full_name, phone, email, parent_name, student_name, source_type, program_interest, instrument_interest, branch_id, owner_user_id, status, interest_level, last_contact_at, next_follow_up_on, converted_student_id, version, created_at'
const closedLead = '(WON,LOST)'
const closedRegistration = '(CANCELLED,REJECTED,EXPIRED)'

function safeSearch(value?: string) {
  return (value ?? '').trim().replace(/[%(),]/g, '').slice(0, 80)
}

function pageNumber(value?: string) {
  const number = Number(value)
  return Number.isInteger(number) && number > 0 && number < 10000 ? number : 1
}

function monthStart(today: string) {
  return `${today.slice(0, 7)}-01T00:00:00+07:00`
}

async function leadIds(query: PromiseLike<{ data: { id?: string; crm_lead_id?: string | null }[] | null; error: { message: string } | null }>) {
  const result = await query
  if (result.error) return { failed: true, ids: [] as string[] }
  const ids = (result.data ?? []).map(row => row.id || row.crm_lead_id).filter((id): id is string => Boolean(id))
  return { failed: false, ids }
}

export async function crmDirectory() {
  const db = await createClient()
  const today = businessDate()
  const start = monthStart(today)
  const [branches, owners, fresh, follow, opportunity, admission, convertedLeads, convertedApps, due, overdue, trial, payment, placement] = await Promise.all([
    db.from('branches').select('id, name').eq('status', 'ACTIVE').order('name'),
    db.from('profiles').select('id, full_name').eq('status', 'ACTIVE').order('full_name').limit(100),
    db.from('crm_leads').select('id', { count: 'exact', head: true }).eq('status', 'NEW'),
    db.from('crm_leads').select('id', { count: 'exact', head: true }).lte('next_follow_up_on', today).not('status', 'in', closedLead),
    db.from('crm_leads').select('id', { count: 'exact', head: true }).in('status', ['TRIAL_BOOKED', 'TRIAL_COMPLETED', 'PROPOSAL_SENT', 'NEGOTIATING']),
    db.from('registration_applications').select('id', { count: 'exact', head: true }).in('status', openRegistrationStatuses).not('crm_lead_id', 'is', null),
    db.from('crm_leads').select('id').gte('converted_at', start).limit(1000),
    db.from('registration_applications').select('crm_lead_id').gte('completed_at', start).not('linked_student_id', 'is', null).not('crm_lead_id', 'is', null).limit(1000),
    db.from('crm_leads').select('id', { count: 'exact', head: true }).eq('next_follow_up_on', today).not('status', 'in', closedLead),
    db.from('crm_leads').select('id', { count: 'exact', head: true }).lt('next_follow_up_on', today).not('status', 'in', closedLead),
    db.from('crm_leads').select('id', { count: 'exact', head: true }).eq('status', 'TRIAL_BOOKED'),
    db.from('registration_applications').select('id', { count: 'exact', head: true }).eq('status', 'PAYMENT_PENDING'),
    db.from('student_placement_cases').select('id', { count: 'exact', head: true }).eq('status', 'UNASSIGNED'),
  ])
  const convertedFailed = Boolean(convertedLeads.error || convertedApps.error)
  const convertedIds = new Set<string>([
    ...((convertedLeads.data ?? []).map(row => row.id)),
    ...((convertedApps.data ?? []).map(row => row.crm_lead_id).filter((id): id is string => Boolean(id))),
  ])
  return {
    today,
    branches: branches.error ? [] : branches.data ?? [],
    owners: owners.error ? [] : owners.data ?? [],
    directoryError: Boolean(branches.error),
    metrics: [
      { id: 'new', title: 'Khách mới', value: shownCount(Boolean(fresh.error), fresh.count) },
      { id: 'follow', title: 'Cần follow-up', value: shownCount(Boolean(follow.error), follow.count) },
      { id: 'opportunity', title: 'Cơ hội', value: shownCount(Boolean(opportunity.error), opportunity.count) },
      { id: 'admission', title: 'Đang nhập học', value: shownCount(Boolean(admission.error), admission.count) },
      { id: 'converted', title: 'Chuyển đổi tháng này', value: convertedFailed ? '—' : String(convertedIds.size) },
    ],
    queue: [
      { id: 'due', label: 'Cần liên hệ hôm nay', value: shownCount(Boolean(due.error), due.count) },
      { id: 'overdue', label: 'Quá hạn follow-up', value: shownCount(Boolean(overdue.error), overdue.count) },
      { id: 'trial', label: 'Đang chờ học thử', value: shownCount(Boolean(trial.error), trial.count) },
      { id: 'payment', label: 'Đang chờ thanh toán', value: shownCount(Boolean(payment.error), payment.count) },
      { id: 'placement', label: 'Đang chờ xếp lớp', value: shownCount(Boolean(placement.error), placement.count) },
    ],
  }
}

async function placementLeadIds(db: Awaited<ReturnType<typeof createClient>>) {
  const placements = await db.from('student_placement_cases').select('registration_application_id').eq('status', 'UNASSIGNED').limit(1000)
  if (placements.error) return { failed: true, ids: [] as string[] }
  const applicationIds = (placements.data ?? []).map(row => row.registration_application_id).filter((id): id is string => Boolean(id))
  if (applicationIds.length === 0) return { failed: false, ids: [] as string[] }
  return leadIds(db.from('registration_applications').select('crm_lead_id').in('id', applicationIds).not('crm_lead_id', 'is', null))
}

export async function loadLeadPage(filters: LeadFilters) {
  const db = await createClient()
  const today = businessDate()
  const page = pageNumber(filters.page)
  const mode = tabMode(filters.tab)
  let idFilter: string[] | null = null
  if (mode === 'admission' || mode === 'converted' || filters.queue === 'payment' || filters.queue === 'placement') {
    const lookedUp = mode === 'admission'
      ? await leadIds(db.from('registration_applications').select('crm_lead_id').in('status', openRegistrationStatuses).not('crm_lead_id', 'is', null).limit(1000))
      : mode === 'converted'
        ? await (async () => {
            const [linked, registered] = await Promise.all([
              leadIds(db.from('crm_leads').select('id').not('converted_student_id', 'is', null).limit(1000)),
              leadIds(db.from('registration_applications').select('crm_lead_id').not('linked_student_id', 'is', null).not('crm_lead_id', 'is', null).limit(1000)),
            ])
            if (linked.failed || registered.failed) return { failed: true, ids: [] as string[] }
            return { failed: false, ids: [...new Set([...linked.ids, ...registered.ids])] }
          })()
        : filters.queue === 'payment'
          ? await leadIds(db.from('registration_applications').select('crm_lead_id').eq('status', 'PAYMENT_PENDING').not('crm_lead_id', 'is', null).limit(1000))
          : await placementLeadIds(db)
    if (lookedUp.failed) return { rows: [] as LeadRow[], registrations: [] as RegistrationSummary[], count: null, page, today, error: true }
    idFilter = lookedUp.ids
    if (idFilter.length === 0) return { rows: [] as LeadRow[], registrations: [] as RegistrationSummary[], count: 0, page, today, error: false }
  }

  let query = db.from('crm_leads').select(leadColumns, { count: 'exact' })
  if (idFilter) query = query.in('id', idFilter)
  const statuses = filters.status ? [filters.status] : tabStatuses(filters.tab)
  if (statuses) query = query.in('status', statuses)
  if (filters.branch) query = query.eq('branch_id', filters.branch)
  if (filters.owner) query = query.eq('owner_user_id', filters.owner)
  if (filters.source) query = query.eq('source_type', filters.source)
  if (filters.queue === 'uncontacted') query = query.eq('status', 'NEW')
  if (filters.queue === 'due') query = query.eq('next_follow_up_on', today).not('status', 'in', closedLead)
  if (filters.queue === 'overdue') query = query.lt('next_follow_up_on', today).not('status', 'in', closedLead)
  if (filters.queue === 'trial') query = query.eq('status', 'TRIAL_BOOKED')
  if (filters.follow === 'today') query = query.eq('next_follow_up_on', today)
  if (filters.follow === 'overdue') query = query.lt('next_follow_up_on', today)
  if (filters.follow === 'scheduled') query = query.not('next_follow_up_on', 'is', null)
  if (filters.follow === 'none') query = query.is('next_follow_up_on', null)
  if (['REFERENCE', 'INTERESTED', 'POTENTIAL'].includes(filters.interest_level ?? '')) query = query.eq('interest_level', filters.interest_level)
  const interest = safeSearch(filters.interest)
  if (interest) query = query.or(`program_interest.ilike.%${interest}%,instrument_interest.ilike.%${interest}%`)
  const search = safeSearch(filters.q)
  if (search) {
    const digits = search.replace(/\D/g, '')
    const clauses = [`full_name.ilike.%${search}%`, `phone.ilike.%${search}%`, `email.ilike.%${search}%`, `student_name.ilike.%${search}%`, `parent_name.ilike.%${search}%`]
    if (digits.length >= 4) clauses.push(`phone_key.ilike.%${digits}%`)
    query = query.or(clauses.join(','))
  }
  const { data, count, error } = await query.order('created_at', { ascending: false }).range((page - 1) * pageSize, page * pageSize - 1)
  if (error) return { rows: [] as LeadRow[], registrations: [] as RegistrationSummary[], count: null, page, today, error: true }
  const rows = (data ?? []) as LeadRow[]
  const ids = rows.map(row => row.id)
  if (ids.length === 0) return { rows, registrations: [] as RegistrationSummary[], count: count ?? 0, page, today, error: false }
  const registrations = await db.from('registration_applications').select('id, crm_lead_id, status, application_code, linked_student_id, invoice_id, payment_confirmed_at').in('crm_lead_id', ids)
  if (registrations.error) return { rows, registrations: [] as RegistrationSummary[], count: count ?? 0, page, today, error: true }
  return { rows, registrations: (registrations.data ?? []) as RegistrationSummary[], count: count ?? 0, page, today, error: false }
}

import Link from 'next/link'
import type { ReactNode } from 'react'
import type { MetricValue } from '../model'
import { displayMetricMoney, statusLabel, statusTone, unresolvedNote, type StatusTone } from '../presentation'
import styles from '../financial-control-tower.module.css'

export function StatusChip({ status, integrity = false }: { status: string; integrity?: boolean }) {
  return <span className={styles.chip} data-tone={statusTone(status, integrity)}>{statusLabel(status)}</span>
}

export function KpiCard({
  title,
  metric,
  currency,
  href,
  change,
  extra,
}: {
  title: string
  metric: MetricValue
  currency: string
  href?: string
  change?: string | null
  extra?: ReactNode
}) {
  const unimplemented = metric.status === 'NOT_IMPLEMENTED'
  const note = unimplemented ? 'Chưa tích hợp nguồn dữ liệu.' : unresolvedNote(metric)
  const inner = <>
    <p className={styles.kpiTitle}>{title}</p>
    <p className={styles.kpiValue}>{unimplemented ? '—' : displayMetricMoney(metric, currency)}</p>
    <div className={styles.kpiMeta}>
      {metric.status === 'PARTIAL' ? <StatusChip status="PARTIAL" /> : null}
      {unimplemented ? <StatusChip status="NOT_IMPLEMENTED" /> : null}
    </div>
    {note ? <p className={styles.kpiNote}>{note}</p> : null}
    {change ? <p className={styles.change}>So với tháng trước: {change}</p> : null}
    {extra}
  </>
  if (!href) return <article className={styles.kpi}>{inner}</article>
  return <Link className={styles.kpi} href={href} prefetch={false}>{inner}</Link>
}

'use client'

import {
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react'

import * as QRCode from 'qrcode'

import {
  getQrRecentScansAction,
  getQrStatusAction,
  mintQrTokenAction,
  startQrSessionAction,
  stopQrSessionAction,
} from './qr-actions'

import { attendanceScanUrl } from './scan-url'

type Branch = {
  id: string
  name: string
  code?: string
}

type Scan = {
  id: string
  employee_id: string
  employee_code?: string | null
  employee_name?: string | null
  work_date?: string
  shift_code: string
  event_type:
    | 'CHECK_IN'
    | 'CHECK_OUT'
  scanned_at: string
  verification_status?:
    | 'WAITING_CHECK_OUT'
    | 'VERIFIED'
    | 'CONFLICT'
    | 'PENDING'
}

function shiftName(code: string) {
  if (code === 'AM') return 'Sáng'
  if (code === 'PM') return 'Chiều'
  return '—'
}

function scanStatus(scan: Scan) {
  if (
    scan.event_type === 'CHECK_IN'
  ) {
    return 'Đã vào ca'
  }

  if (
    scan.verification_status
    === 'VERIFIED'
  ) {
    return 'Đã xác nhận QR'
  }

  if (
    scan.verification_status
    === 'CONFLICT'
  ) {
    return 'Cần xử lý'
  }

  return 'Đã ra ca'
}

export default function QrAttendanceClient({
  branches,
}: {
  branches: Branch[]
}) {
  const [
    branchId,
    setBranchId,
  ] = useState(
    branches[0]?.id ?? '',
  )

  const [
    sessionId,
    setSessionId,
  ] = useState<string | null>(
    null,
  )

  const [
    token,
    setToken,
  ] = useState('')

  const [
    expiresAt,
    setExpiresAt,
  ] = useState('')

  const [
    qrImage,
    setQrImage,
  ] = useState('')

  const [
    secondsLeft,
    setSecondsLeft,
  ] = useState(0)

  const [
    scans,
    setScans,
  ] = useState<Scan[] | null>(
    null,
  )

  const [
    error,
    setError,
  ] = useState('')

  const [
    busy,
    setBusy,
  ] = useState(false)

  const rotationTimer =
    useRef<
      ReturnType<typeof setTimeout>
      | undefined
    >(undefined)

  const branch = useMemo(
    () =>
      branches.find(
        (item) =>
          item.id === branchId,
      ),
    [branches, branchId],
  )

  useEffect(() => {
    let cancelled = false

    async function load() {
      if (!branchId) {
        setSessionId(null)
        return
      }

      setError('')
      setToken('')
      setQrImage('')
      setExpiresAt('')

      const result =
        await getQrStatusAction(
          branchId,
        )

      if (cancelled) return

      if (!result.ok) {
        setError(result.error)
        setSessionId(null)
        return
      }

      const data = result.data

      if (
        data?.status === 'ACTIVE'
        && data?.session_id
      ) {
        setSessionId(
          String(data.session_id),
        )
      } else {
        setSessionId(null)
      }
    }

    load()

    return () => {
      cancelled = true
    }
  }, [branchId])

  useEffect(() => {
    let cancelled = false

    async function rotate() {
      if (!sessionId) return

      const result =
        await mintQrTokenAction(
          sessionId,
        )

      if (cancelled) return

      if (!result.ok) {
        setError(result.error)
        return
      }

      const data = result.data

      setToken(
        String(data.token ?? ''),
      )

      setExpiresAt(
        String(
          data.expires_at ?? '',
        ),
      )

      setError('')

      rotationTimer.current =
        setTimeout(
          rotate,
          55000,
        )
    }

    if (sessionId) {
      rotate()
    }

    return () => {
      cancelled = true

      if (
        rotationTimer.current
      ) {
        clearTimeout(
          rotationTimer.current,
        )
      }
    }
  }, [sessionId])

  useEffect(() => {
    if (!token) return

    let cancelled = false

    const url = attendanceScanUrl(
      token,
      process.env.NEXT_PUBLIC_APP_URL,
      window.location.origin,
    )

    QRCode
      .toDataURL(
        url,
        {
          width: 360,
          margin: 2,
          errorCorrectionLevel: 'M',
        },
      )
      .then((image) => {
        if (!cancelled) {
          setQrImage(image)
        }
      })
      .catch(() => {
        if (!cancelled) {
          setError(
            'Không thể tạo mã QR.',
          )
        }
      })

    return () => {
      cancelled = true
    }
  }, [token])

  useEffect(() => {
    const timer =
      setInterval(() => {
        if (!expiresAt) {
          setSecondsLeft(0)
          return
        }

        setSecondsLeft(
          Math.max(
            0,
            Math.ceil(
              (
                new Date(
                  expiresAt,
                ).getTime()
                - Date.now()
              ) / 1000,
            ),
          ),
        )
      }, 250)

    return () =>
      clearInterval(timer)
  }, [expiresAt])

  useEffect(() => {
    let cancelled = false

    async function loadScans() {
      if (!branchId) {
        setScans([])
        return
      }

      const result =
        await getQrRecentScansAction(
          branchId,
        )

      if (cancelled) return

      if (!result.ok) {
        setError(result.error)
        setScans(null)
        return
      }

      const rows = Array.isArray(result.data)
        ? result.data
        : []

      setScans(rows as Scan[])
    }

    loadScans()

    const timer =
      setInterval(
        loadScans,
        5000,
      )

    return () => {
      cancelled = true
      clearInterval(timer)
    }
  }, [branchId])

  async function start() {
    if (
      !branchId
      || busy
    ) {
      return
    }

    setBusy(true)
    setError('')

    const result =
      await startQrSessionAction(
        branchId,
      )

    setBusy(false)

    if (!result.ok) {
      setError(result.error)
      return
    }

    const data =
      result.data

    if (data?.session_id) {
      setSessionId(
        String(data.session_id),
      )
    }
  }

  async function stop() {
    if (
      !sessionId
      || busy
    ) {
      return
    }

    setBusy(true)
    setError('')

    const result =
      await stopQrSessionAction(
        sessionId,
      )

    setBusy(false)

    if (!result.ok) {
      setError(result.error)
      return
    }

    setSessionId(null)
    setToken('')
    setQrImage('')
    setExpiresAt('')
    setSecondsLeft(0)
  }

  if (!branches.length) {
    return (
      <section className="vibe-card">
        <h2>QR chấm công</h2>

        <p className="vibe-empty">
          Tài khoản chưa có chi nhánh
          được phép quản lý chấm công.
        </p>
      </section>
    )
  }

  return (
    <section className="vibe-card">
      <div className="vibe-actions">
        <div>
          <h2>
            QR chấm công
          </h2>

          <p>
            Mã tự đổi mỗi 60 giây.
            Nhân viên phải dùng tài khoản
            của chính mình.
          </p>
        </div>

        <label className="vibe-field">
          <span>Chi nhánh</span>

          <select
            value={branchId}
            onChange={(event) => {
              setSessionId(null)
              setToken('')
              setQrImage('')
              setExpiresAt('')
              setSecondsLeft(0)
              setBranchId(event.target.value)
            }}
          >
            {branches.map(
              (item) => (
                <option
                  key={item.id}
                  value={item.id}
                >
                  {item.name}
                </option>
              ),
            )}
          </select>
        </label>

        {sessionId ? (
          <>
            <span className="vibe-badge">
              Đang hoạt động
            </span>

            <button
              type="button"
              className="vibe-button"
              onClick={stop}
              disabled={busy}
            >
              Dừng QR
            </button>
          </>
        ) : (
          <button
            type="button"
            className="vibe-button"
            onClick={start}
            disabled={busy}
          >
            Mở chấm công
          </button>
        )}
      </div>

      {error && (
        <div className="vibe-card">
          <strong>
            Không thể thực hiện
          </strong>

          <p>{error}</p>
        </div>
      )}

      <div className="vibe-grid">
        <section className="vibe-card">
          {sessionId && qrImage ? (
            <div
              style={{
                textAlign: 'center',
              }}
            >
              <img
                src={qrImage}
                alt="QR chấm công VIBE"
                style={{
                  display: 'block',
                  width: '100%',
                  maxWidth: 360,
                  margin: '0 auto',
                }}
              />

              <h3>
                {branch?.name}
              </h3>

              <div
                style={{
                  fontSize: '2.5rem',
                  fontWeight: 700,
                  fontVariantNumeric:
                    'tabular-nums',
                }}
              >
                {secondsLeft}s
              </div>

              <p>
                Hết thời gian hệ thống
                tự sinh mã mới.
              </p>
            </div>
          ) : (
            <p className="vibe-empty">
              {sessionId
                ? 'Đang tạo mã QR...'
                : 'Mở chấm công để bắt đầu.'}
            </p>
          )}
        </section>

        <section className="vibe-card">
          <h3>
            Hoạt động gần đây
          </h3>

          {scans === null ? (
            <p>—</p>
          ) : !scans.length ? (
            <p className="vibe-empty">
              Chưa có lượt quét.
            </p>
          ) : (
            <div className="vibe-table-scroll">
              <table className="vibe-table">
                <thead>
                  <tr>
                    <th>Nhân viên</th>
                    <th>Mã nhân viên</th>
                    <th>Ca</th>
                    <th>Vào ca / Ra ca</th>
                    <th>Trạng thái</th>
                    <th>Thời gian</th>
                  </tr>
                </thead>

                <tbody>
                  {scans.map(
                    (scan) => (
                      <tr key={scan.id}>
                        <td>
                          <strong>
                            {scan.employee_name
                              || 'Nhân viên'}
                          </strong>
                        </td>

                        <td>
                          {scan.employee_code
                            || '—'}
                        </td>

                        <td>
                          {shiftName(
                            scan.shift_code,
                          )}
                        </td>

                        <td>
                          {scan.event_type
                            === 'CHECK_IN'
                            ? 'Vào ca'
                            : 'Ra ca'}
                        </td>

                        <td>
                          <span className="vibe-badge">
                            {scanStatus(scan)}
                          </span>
                        </td>

                        <td>
                          {new Date(
                            scan.scanned_at,
                          ).toLocaleTimeString(
                            'vi-VN',
                            {
                              timeZone:
                                'Asia/Ho_Chi_Minh',
                              hour:
                                '2-digit',
                              minute:
                                '2-digit',
                              second:
                                '2-digit',
                            },
                          )}
                        </td>
                      </tr>
                    ),
                  )}
                </tbody>
              </table>
            </div>
          )}
        </section>
      </div>

      <section className="vibe-card">
        <h3>Vấn đề từ QR</h3>
        {scans === null ? (
          <p>—</p>
        ) : !scanIssues(scans).length ? (
          <p className="vibe-empty">
            Không có vào ca thiếu ra ca
            trong các lượt vừa tải.
          </p>
        ) : (
          scanIssues(scans).map(
            (line) => (
              <p key={line}>{line}</p>
            ),
          )
        )}
      </section>
    </section>
  )
}

function scanIssues(scans: Scan[]) {
  const groups = new Map<string, Scan[]>()

  for (const scan of scans) {
    const key = [
      scan.employee_id,
      scan.work_date || '',
      scan.shift_code,
    ].join('|')
    const list = groups.get(key) || []
    list.push(scan)
    groups.set(key, list)
  }

  const lines: string[] = []

  for (const group of groups.values()) {
    const name =
      group[0].employee_name
      || group[0].employee_code
      || 'Nhân viên'
    const hasIn = group.some(
      (scan) =>
        scan.event_type === 'CHECK_IN',
    )
    const hasOut = group.some(
      (scan) =>
        scan.event_type === 'CHECK_OUT',
    )

    if (hasIn && !hasOut) {
      lines.push(
        name
        + ' · Có vào ca, thiếu ra ca',
      )
    }

    if (
      group.some(
        (scan) =>
          scan.verification_status
          === 'CONFLICT',
      )
    ) {
      lines.push(
        name
        + ' · Cần xử lý',
      )
    }
  }

  return lines
}

import { adminClient, pageNumber, uuidPattern, validDate, type Params } from '../finance/operations'
import { branches, rows } from '../finance/query'
import { teachers } from '../feedback/data'
import {
  addCalendarDays,
  assignmentPageSize,
  assignmentTabs,
  assignmentWarnings,
  assignmentWindowCap,
  classesNeedingPrimary,
  isCurrentTeaching,
  isOperationalSubstitute,
  vietnamToday,
  warningSessionCount,
  type AssignmentSession,
  type AssignmentTab,
  type ClassTeacherAssignment,
} from './model'

const sessionFields = 'session_id,class_id,branch_id,occurrence_date,starts_at,ends_at,status,teacher_id,primary_teacher_id,assignment_type,reason,is_locked'
const statuses = ['SCHEDULED', 'COMPLETED', 'CANCELLED']

export async function loadAssignmentCenter(params: Params) {
  const db = await adminClient()
  const today = vietnamToday()
  const from = validDate(params.from || '') ? params.from! : today
  const to = validDate(params.to || '') ? params.to! : addCalendarDays(today, 30)
  const rangeFrom = from <= to ? from : to
  const rangeTo = from <= to ? to : from
  const tab = assignmentTabs.some(([id]) => id === params.tab) ? params.tab as AssignmentTab : 'needed'
  const page = pageNumber(params.page)
  const branchId = uuidPattern.test(params.branch || '') ? params.branch! : ''
  const teacherId = uuidPattern.test(params.teacher || '') ? params.teacher! : ''
  const status = statuses.includes(params.status || '') ? params.status! : ''
  const filters = { tab, branch: branchId, teacher: teacherId, from: rangeFrom, to: rangeTo, status, page: String(page) }

  let display = db.from('session_actual_teachers').select(sessionFields).gte('occurrence_date', rangeFrom).lte('occurrence_date', rangeTo)
  if (branchId) display = display.eq('branch_id', branchId)
  if (teacherId) display = display.eq('teacher_id', teacherId)
  if (status) display = display.eq('status', status)
  // Conflict schedule ignores branch and status filters so a hidden branch cannot conceal an overlap.
  let conflict = db.from('session_actual_teachers').select(sessionFields).gte('occurrence_date', rangeFrom).lte('occurrence_date', rangeTo)
  if (teacherId) conflict = conflict.eq('teacher_id', teacherId)
  const [sessionResult, conflictResult, branchOptions, teacherOptions] = await Promise.all([
    display.order('starts_at').order('session_id').limit(assignmentWindowCap + 1).returns<AssignmentSession[]>(),
    conflict.order('starts_at').order('session_id').limit(assignmentWindowCap + 1).returns<AssignmentSession[]>(),
    branches(db),
    teachers(db),
  ])
  if (sessionResult.error || !sessionResult.data || conflictResult.error || !conflictResult.data) {
    return { ok: false as const, filters, branches: branchOptions, teachers: teacherOptions }
  }
  const truncated = sessionResult.data.length > assignmentWindowCap || conflictResult.data.length > assignmentWindowCap
  const sessions = sessionResult.data.slice(0, assignmentWindowCap)
  const conflictSessions = conflictResult.data.slice(0, assignmentWindowCap)
  const classIds = [...new Set(sessions.map((session) => session.class_id))]
  const branchIds = [...new Set([...sessions, ...conflictSessions].map((session) => session.branch_id))]
  const sessionTeacherIds = [...new Set(sessions.flatMap((session) => [session.teacher_id, session.primary_teacher_id].filter((id): id is string => !!id)))]
  const assignmentSource = sessionTeacherIds.length
    ? await rows(db.from('class_teachers').select('class_id,teacher_id,teacher_role,is_active,assigned_at,ended_at').in('teacher_id', sessionTeacherIds).returns<Omit<ClassTeacherAssignment, 'branch_id'>[]>())
    : []
  const assignmentClassIds = [...new Set(assignmentSource.map((row) => row.class_id))]
  const classLookupIds = [...new Set([...classIds, ...assignmentClassIds])]
  const teacherIds = [...new Set([...sessionTeacherIds, ...assignmentSource.map((row) => row.teacher_id)])]
  const [classRows, branchRows, teacherRows, linkRows] = await Promise.all([
    classLookupIds.length ? rows(db.from('classes').select('id,name,branch_id').in('id', classLookupIds).returns<{ id: string; name: string; branch_id: string }[]>()) : [],
    branchIds.length ? rows(db.from('branches').select('id,name').in('id', branchIds).returns<{ id: string; name: string }[]>()) : [],
    teacherIds.length ? rows(db.from('teachers').select('id,full_name,teacher_code').in('id', teacherIds).returns<{ id: string; full_name: string | null; teacher_code: string }[]>()) : [],
    teacherIds.length ? rows(db.from('teacher_branches').select('teacher_id,branch_id').in('teacher_id', teacherIds).returns<{ teacher_id: string; branch_id: string }[]>()) : [],
  ])
  const classBranch = new Map(classRows.map((row) => [row.id, row.branch_id]))
  const assignments: ClassTeacherAssignment[] = assignmentSource.flatMap((row) => {
    const branch = classBranch.get(row.class_id)
    return branch ? [{ ...row, branch_id: branch }] : []
  })
  const classes = new Map(classRows.map((row) => [row.id, row.name]))
  const branchNames = new Map(branchRows.map((row) => [row.id, row.name]))
  const teacherNames = new Map(teacherRows.map((row) => [row.id, { name: row.full_name || row.teacher_code, code: row.teacher_code }]))
  const eligible = new Set(linkRows.map((row) => `${row.teacher_id}:${row.branch_id}`))
  const classNeeds = classesNeedingPrimary(sessions, today)
  const warnings = assignmentWarnings(sessions, today, eligible, conflictSessions)
  const warningSessions = warningSessionCount(warnings)
  return {
    ok: true as const,
    truncated,
    filters,
    today,
    branches: branchOptions,
    teachers: teacherOptions,
    sessions,
    assignments,
    classNeeds,
    classes,
    branchNames,
    teacherNames,
    warnings,
    counts: {
      needed: classNeeds.length,
      active: sessions.filter((session) => isCurrentTeaching(session, today)).length,
      substitute: sessions.filter((session) => isOperationalSubstitute(session, today)).length,
      warnings: warningSessions,
    },
    page,
  }
}

