  assert.throws(() => parseLegacyCsv(csv([source, source])), /trùng/)
  assert.throws(() => parseLegacyCsv(csv([source]).slice(0, -1)), /ngoặc kép/)
  assert.throws(() => parseLegacyCsv('name,value\na,b'), /Cột/)
})
