  assert.deepEqual(ready.missingSecrets, ['ZALO_OA_ACCESS_TOKEN', 'ZALO_OA_REFRESH_TOKEN', 'ZALO_APP_SECRET', 'ZALO_OA_SECRET_KEY'])
